const TOKEN_PREFIX = "tfk_";
const PREFIX_LENGTH = 12;
const MAX_USABLE_TOKENS = 5;
const DAY_MS = 24 * 60 * 60 * 1000;

function deny(actor: Actor, action: PermissionAction, required: Role): void {
  if (hasRoleAtLeast(actor.role, required)) return;
  throw new PermissionDeniedError(action, {
    allowed: false,
    action,
    resourceKind: "member",
    reason: "denied_by_role",
  });
}

function isUsable(token: ApiToken, now: Date): boolean {
  return token.revokedAt === null && Date.parse(token.expiresAt) > now.getTime();
}

export async function createApiToken(
  actor: Actor,
  input: CreateApiTokenInput,
): Promise<{ token: string; apiToken: ApiToken }> {
  const parsed = createApiTokenSchema.parse(input);
  assertOrgScope(actor, parsed.orgId);
  if (parsed.scope === "write") deny(actor, "member:invite", "member");

  const now = new Date();
  const existing = await tokenRepo.listApiTokensForUser(parsed.orgId, actor.userId);
  if (existing.filter((t) => isUsable(t, now)).length >= MAX_USABLE_TOKENS) {
    throw new Error(`At most ${MAX_USABLE_TOKENS} active API tokens are allowed`);
  }

  const token = `${TOKEN_PREFIX}${randomToken()}`;
  const apiToken = await tokenRepo.insertApiToken({
    orgId: parsed.orgId,
    userId: actor.userId,
    name: parsed.name,
    scope: parsed.scope,
    prefix: token.slice(0, PREFIX_LENGTH),
    tokenHash: hashToken(token),
    expiresAt: toIsoTimestamp(new Date(now.getTime() + parsed.expiresInDays * DAY_MS)),
    createdAt: toIsoTimestamp(now),
  });

  await emit("api_token.created", {
    ...envelope(apiToken.orgId, actor.userId),
    tokenId: apiToken.id,
    userId: apiToken.userId,
    name: apiToken.name,
    scope: apiToken.scope,
  });

  return { token, apiToken };
