export async function listApiTokens(
  actor: Actor,
  orgId: OrgId,
  userId?: UserId,
): Promise<readonly ApiToken[]> {
  assertOrgScope(actor, orgId);
  const target = userId ?? actor.userId;
  if (target !== actor.userId) deny(actor, "member:read", "admin");
  return tokenRepo.listApiTokensForUser(orgId, target);
}

async function revoke(
  actorId: UserId,
  token: ApiToken,
  at: IsoTimestamp,
): Promise<ApiToken> {
  if (token.revokedAt !== null) return token;
  const updated = requireFound(
    await tokenRepo.markRevoked(token.orgId, token.id, at),
    "ApiToken",
    token.id,
  );
  await emit("api_token.revoked", {
    ...envelope(token.orgId, actorId),
    tokenId: token.id,
    userId: token.userId,
  });
  return updated;
}

export async function revokeApiToken(
  actor: Actor,
  orgId: OrgId,
  tokenId: string,
): Promise<ApiToken> {
  assertOrgScope(actor, orgId);
  const token = requireFound(
    await tokenRepo.findApiTokenById(orgId, tokenId),
    "ApiToken",
    tokenId,
  );
  if (token.userId !== actor.userId) deny(actor, "member:remove", "admin");
  return revoke(actor.userId, token, toIsoTimestamp(new Date()));
