export async function revokeAllTokensForUser(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  const at = toIsoTimestamp(new Date());
  const tokens = await tokenRepo.listApiTokensForUser(orgId, userId);
  for (const token of tokens) {
    await revoke(actor.userId, token, at);
  }
}

