  if (!token.startsWith(TOKEN_PREFIX)) return null;
  const now = new Date();
  const apiToken = await tokenRepo.findApiTokenByHash(hashToken(token));
  if (!apiToken || !isUsable(apiToken, now)) return null;

  const org = await orgRepo.findOrgById(apiToken.orgId);
  if (!org || org.archivedAt !== null) return null;

  const member = await memberRepo.findMember(apiToken.orgId, apiToken.userId);
  if (!member || member.status !== "active" || member.archivedAt !== null) return null;

  await tokenRepo.markUsed(apiToken.orgId, apiToken.id, toIsoTimestamp(now));

  return {
    userId: apiToken.userId,
    orgId: apiToken.orgId,
    role: apiToken.scope === "read" ? "viewer" : member.role,
  };
}
